#!/usr/bin/env python3
# SPDX-License-Identifier: AGPL-3.0-only
"""Fixture for tests/jd2_earth_rotation_erfa_oracle.rs.

Step 1 (--epochs-only) writes epochs.csv from the fixed rules of the pre-registration:
two-part UT1 Julian dates (day, frac) and the TT - UT1 offset used to form TT.
Step 2 runs the oracle, pyerfa (ERFA, the BSD-licensed release of the SOFA routines), and
writes erfa.csv: per epoch, erfa.gmst82(ut1_day, ut1_frac) and the 9 elements (row-major) of
erfa.c2t06a(tt_day, tt_frac, ut1_day, ut1_frac, xp, yp) with xp = 0.1", yp = 0.3".
Run from the repository root (pyerfa 2.0.1.5, numpy):
    python -I tests/fixtures/jd2_earth_rotation_erfa_oracle/generate_jd2_earth_rotation_erfa_oracle.py [--epochs-only]
"""
import csv
import random
import sys
from pathlib import Path

DIR = Path(__file__).resolve().parent
AS2R = 3.141592653589793 / 180.0 / 3600.0
XP, YP = 0.1 * AS2R, 0.3 * AS2R


def epochs():
    rows = []
    # Fixed: J2000.0 and 2026-10-13 0h UT1, each also +1 us, +10 us and +50 us later,
    # so the 50 us single-f64 floor is inside the set.
    for (day, frac) in ((2451545.0, 0.0), (2461326.0, 0.5)):
        for us in (0, 1, 10, 50):
            rows.append((day, frac + us * 1e-6 / 86400.0, 69.184))
    rng = random.Random(20261013 + 20)
    for _ in range(32):
        day = float(rng.randint(2444240, 2469807))
        frac = round(rng.random(), 12)
        tt_minus_ut1 = round(rng.uniform(32.184 + 10.0 - 1.0, 32.184 + 37.0 + 1.0), 7)
        rows.append((day, frac, tt_minus_ut1))
    return rows


def main():
    step = 1 if len(sys.argv) > 1 and sys.argv[1] == "--epochs-only" else 2
    rows = epochs()
    with open(DIR / "epochs.csv", "w", newline="") as f:
        f.write("# ut1_day,ut1_frac,tt_minus_ut1_s (generated by generate_jd2_earth_rotation_erfa_oracle.py)\n")
        w = csv.writer(f, lineterminator="\n")
        for r in rows:
            w.writerow([repr(float(x)) for x in r])
    if step == 1:
        return
    import erfa
    import numpy as np
    with open(DIR / "erfa.csv", "w", newline="") as f:
        f.write(f"# pyerfa {erfa.__version__} (liberfa {erfa.version.erfa_version}): "
                "gmst82(ut1); c2t06a(tt, ut1, 0.1as, 0.3as)[9] row-major\n")
        w = csv.writer(f, lineterminator="\n")
        for (day, frac, dtt) in rows:
            tt_frac = frac + dtt / 86400.0
            g = erfa.gmst82(day, frac)
            m = erfa.c2t06a(day, tt_frac, day, frac, XP, YP)
            w.writerow([repr(float(g))] + [repr(float(v)) for v in np.asarray(m).ravel()])


if __name__ == "__main__":
    main()
